<script setup lang="ts">
import {onMounted,ref} from 'vue'
import {usePayrollPage} from '../payrollPage'
import {WorkforceApiError} from '../api'
import {copy} from '../payrollUi'
import type {ChangeWrite,PayChange} from '../payChanges'
import type {PayProfile,SalaryTemplate,PrDocument,LineInput} from '../payrollTypes'
import type {Option} from '../types'
import PayChangeEditor from './PayChangeEditor.vue'
import PayChangeReview from './PayChangeReview.vue'
const props=defineProps<{seed:ChangeWrite;templates:SalaryTemplate[];employees:Option[];profiles:PayProfile[];birthDates:Record<string,string>;prDocuments:Record<string,PrDocument[]>}>(),emit=defineEmits<{cancel:[]}>()
const {api,current,english,message,base,store}=usePayrollPage(),x=(z:string,e:string)=>english()?e:z
const prepared=ref<ChangeWrite|null>(null),preparing=ref(false),existing=ref<PayChange|null>(null),mergeAccepted=ref(false)
const saved=ref<PayChange|null>(null),editing=ref(true),busy=ref(false),failure=ref(''),pending=ref<{id:string;body:ChangeWrite}|null>(null)
async function prepare(){if(preparing.value)return;preparing.value=true;failure.value='';const owner=store.value;try{const proposal=copy(props.seed);const [requests,baselines]=await Promise.all([api().get<PayChange[]>('/pay-change-requests?companyId='+proposal.companyId),Promise.all(proposal.months.map(m=>api().get<LineInput>(`/pay-change-monthly-baseline?companyId=${proposal.companyId}&employeeId=${proposal.employeeId}&month=${m.month}`)))]);if(!current()||owner!==store.value)return;proposal.months.forEach((m,i)=>m.input.expectedVersion=baselines[i].version);existing.value=(Array.isArray(requests)?requests:[]).find(r=>r.employeeId===proposal.employeeId&&['draft','submitted','withdrawn'].includes(r.status)&&(r.effectiveDate===proposal.effectiveDate||r.content.months.some(m=>proposal.months.some(v=>v.month===m.month))))||null;prepared.value=proposal}catch(e){if(current()&&owner===store.value)failure.value=message(e)}finally{if(current())preparing.value=false}}
function merge(){const r=existing.value,p=prepared.value;if(!r||!p||!['draft','withdrawn'].includes(r.status))return;const retained=r.content.months.filter(m=>!p.months.some(v=>v.month===m.month)).map(m=>({month:m.month,input:{expectedVersion:m.before.version,workingDays:m.after.workingDays,payableDays:m.after.payableDays,unitsReviewed:m.after.unitsReviewed,specialDaysReviewed:m.after.specialDaysReviewed,items:copy(m.after.items),note:m.after.note,cdacReview:copy(m.after.cdacReview||null),cdacAutomatic:!m.after.cdacReview}}));p.months=[...retained,...p.months];if(r.content.supplemental?.length)p.supplemental=[...copy(r.content.supplemental.filter(v=>!p.supplemental?.some(n=>n.id===v.id))),...(p.supplemental||[])];p.effectiveDate=r.effectiveDate;p.expectedRevision=r.revision;mergeAccepted.value=true}
onMounted(()=>void prepare())
async function save(id:string,body:ChangeWrite){if(busy.value)return;if(!pending.value)pending.value={id,body:copy(body)};const command=pending.value,owner=store.value;busy.value=true;failure.value='';try{const request=await api().put<PayChange>('/pay-change-requests/'+command.id,command.body);if(current()&&owner===store.value){saved.value=request;pending.value=null;editing.value=false}}catch(e){if(current()&&owner===store.value){if(e instanceof WorkforceApiError&&e.status>=400&&e.status<500){pending.value=null;failure.value=message(e)}else failure.value=x('草稿保存结果未确认，原输入已保留；请重试同一草稿。','Draft result uncertain. Retry the same draft; entered data is preserved.')}}finally{if(current())busy.value=false}}
</script>
<template><section class="wf-section"><p role="status">{{x('此变更需要审批，尚未保存为有效工资。请核对保留的输入并填写变更理由，先保存申请草稿。','Approval is required. Review the preserved input and provide a reason before saving a draft.')}}</p><p v-if="failure" role="alert">{{failure}}</p><p v-if="preparing" role="status">{{x('核对有效基线和已有申请…','Checking effective baseline and existing requests…')}}</p><button v-if="!prepared&&!preparing" type="button" @click="emit('cancel')">{{x('返回原表单','Back to original form')}}</button><button v-if="!prepared&&!preparing" type="button" @click="prepare">{{x('重试核对申请基线','Retry request baseline')}}</button><section v-if="existing&&!mergeAccepted"><p role="status">{{x('该主体已有开放申请。原表单输入仍保留；请先核对已有内容。','An open request exists. Original input is preserved; review existing contents first.')}}</p><PayChangeReview :request="existing" :head-office="false" :busy="false" read-only/><button v-if="['draft','withdrawn'].includes(existing.status)" type="button" @click="merge">{{x('合并到已有草稿并核对','Merge into existing draft for review')}}</button><p v-else>{{x('已提交内容不可变；请先到申请页撤回后继续，原输入不会被覆盖。','Submitted contents are immutable. Withdraw from the request page before continuing.')}}</p><RouterLink class="wf-button" :to="{path:base+'/pay-change-requests',query:{companyId:seed.companyId,requestId:existing?.id}}">{{x('前往工资变更申请','Open pay change requests')}}</RouterLink><button type="button" @click="emit('cancel')">{{x('返回原表单','Back to original form')}}</button></section><PayChangeEditor v-if="editing&&prepared&&(!existing||mergeAccepted)" :request="existing" :seed="prepared" :company-id="seed.companyId" :salary-access="true" :employees="employees" :profiles="profiles" :birth-dates="birthDates" :pr-documents="prDocuments" :templates="templates" :adoptions="[]" :scheduled-dates="{}" :busy="busy||!!pending" @save="save" @cancel="emit('cancel')"/><button v-if="pending" type="button" :disabled="busy" @click="save(pending.id,pending.body)">{{x('重试保存草稿','Retry draft save')}}</button><template v-if="saved&&!editing"><p role="status">{{x('申请草稿已保存，尚未提交审批，尚未计入工资。请在工资变更申请页核对并显式提交。','Draft saved, not submitted or included in payroll. Review and explicitly submit from pay change requests.')}}</p><PayChangeReview :request="saved" :head-office="false" :busy="busy" read-only/><RouterLink class="wf-button" :to="{path:base+'/pay-change-requests',query:{companyId:seed.companyId,requestId:saved.id}}">{{x('前往工资变更申请','Open pay change requests')}}</RouterLink><button type="button" @click="emit('cancel')">{{x('返回原表单','Back to original form')}}</button></template></section></template>
